def loguniform(rng, lo, hi):
    return float(np.exp(rng.uniform(np.log(lo), np.log(hi))))

N_INC_MAX = N_INC_RANGE[1]

def sample_medium(rng):
    """Случайные активные etal-круги на неизменной Gmsh-сетке.

    Возвращает узловые A,n (для SVD), поэлементные A,n (для FEM) и таблицу кругов.
    """
    n_active = int(rng.integers(N_INC_RANGE[0], N_INC_RANGE[1] + 1))
    selected = rng.choice(len(etal_circles_default), size=n_active, replace=False)
    A_cells = np.ones(NCELL, dtype=np.float64)
    n_cells = np.ones(NCELL, dtype=np.float64)
    table = np.full((N_INC_MAX, 5), np.nan, dtype=np.float32)
    for j, circle_id in enumerate(selected):
        cx, cy, radius, *_ = etal_circles_default[int(circle_id)]
        a_in = loguniform(rng, *A_IN_RANGE)
        n_in = loguniform(rng, *N_IN_RANGE)
        cells = solver.circle_cells[int(circle_id)]
        A_cells[cells] = a_in
        n_cells[cells] = n_in
        table[j] = (cx, cy, radius, a_in, n_in)
    return (solver.nodal_coefficients(A_cells),
            solver.nodal_coefficients(n_cells), A_cells, n_cells, table)

def sample_directions(rng):
    if DIR_MODE == "equispaced":
        th0 = rng.uniform(0.0, 2*np.pi / N_DIRS)
        return th0 + 2*np.pi * np.arange(N_DIRS) / N_DIRS
    if DIR_MODE == "random":
        return rng.uniform(0.0, 2*np.pi, size=N_DIRS)
    raise ValueError(f"DIR_MODE = {DIR_MODE!r}")

def incident(k0, theta):
    return np.exp(1j * k0 * (X * np.cos(theta) + Y * np.sin(theta)))

# @title Loss в масштабе поля, batches, optimizer и проверка проекции
_target_std=jnp.asarray(np.stack([cur_std,cui_std],axis=-1))
def field_metadata(fields, cr, ci):
    reconstructed=u_real_mean+cr@Phi_ur.T+1j*(u_imag_mean+ci@Phi_ui.T)
    floor2=np.sum(np.abs(fields-reconstructed)**2,axis=1)
    norm2=np.sum(np.abs(fields)**2,axis=1)
    return np.stack([norm2,floor2],axis=1).astype(np.float32)
D_train=field_metadata(u_train,C_ur_train,C_ui_train)
D_val=field_metadata(u_val,C_ur_val,C_ui_val)
D_test=field_metadata(u_test,C_ur_test,C_ui_test)
def create_batches(X,Y,D,batch_size,rng,shuffle=True):
    idx=rng.permutation(len(X)) if shuffle else np.arange(len(X))
    for start in range(0,len(X),batch_size):
        j=idx[start:start+batch_size]
        yield jnp.asarray(X[j]),jnp.asarray(Y[j]),jnp.asarray(D[j])
def relative_l2_latent_loss(params,tokens,target):
    error=apply_model(params,tokens)-target
    return jnp.mean(jnp.linalg.norm(error,axis=(1,2))/(jnp.linalg.norm(target,axis=(1,2))+1e-12))
def relative_field_loss(params,tokens,target,meta):
    delta=(apply_model(params,tokens)-target)*_target_std
    err2=jnp.sum(delta**2,axis=(1,2))+meta[:,1]
    return jnp.mean(jnp.sqrt(jnp.maximum(err2,1e-24)/jnp.maximum(meta[:,0],1e-24)))
steps_per_epoch=(len(X_train)+BATCH_SIZE-1)//BATCH_SIZE
lr_schedule=optax.exponential_decay(LEARNING_RATE,transition_steps=100*steps_per_epoch,decay_rate=.5,staircase=True,end_value=1e-5)
optimizer=optax.chain(optax.clip_by_global_norm(1.0),optax.adam(lr_schedule))
@jax.jit
def train_step(params,opt_state,X_batch,Y_batch,D_batch):
    loss,grads=jax.value_and_grad(relative_field_loss)(params,X_batch,Y_batch,D_batch)
    updates,opt_state=optimizer.update(grads,opt_state,params)
    return optax.apply_updates(params,updates),opt_state,loss
@jax.jit
def eval_step(params,X_batch,Y_batch,D_batch):
    return relative_field_loss(params,X_batch,Y_batch,D_batch)

# @title Ошибка в узлах и интегральная FEM L2-ошибка
from scipy.sparse import coo_matrix
def p1_mass_matrix(coords,triangles):
    p=coords[triangles]
    a=p[:,1]-p[:,0]; b=p[:,2]-p[:,0]
    area=.5*np.abs(a[:,0]*b[:,1]-a[:,1]*b[:,0])
    if np.any(area<=0): raise ValueError("Вырожденные треугольники")
    local=area[:,None,None]/12*(np.ones((3,3))+np.eye(3))
    rows=np.repeat(triangles,3,axis=1).ravel()
    cols=np.tile(triangles,(1,3)).ravel()
    return coo_matrix((local.ravel(),(rows,cols)),shape=(len(coords),len(coords))).tocsr()
MASS_MATRIX=p1_mass_matrix(geo["dof_coords"],geo["triangles"])
def mass_norm2(values):
    v=np.atleast_2d(values).astype(np.complex128)
    return np.maximum(np.real(np.sum(v.conj()*(MASS_MATRIX@v.T).T,axis=1)),0)
def relative_fem_l2(true,pred):
    return np.sqrt(mass_norm2(pred-true)/np.maximum(mass_norm2(true),1e-30))
def summarize_errors(values):
    return {"mean":float(np.mean(values)),"median":float(np.median(values)),"p95":float(np.percentile(values,95)),"max":float(np.max(values))}
